let SIMD_TO_WORDSIZE_CONV =
  let pths = map (fun th -> rand (lhs (concl th)), th)
    (CONJUNCTS simd_to_wordsize) in
  function
  | Comb(Const("simd_to_wordsize",_),v) ->
    (try assoc v pths
    with Failure _ -> failwith "SIMD_TO_WORDSIZE_CONV")
