    ASM_REWRITE_TAC [list_linear_read_byte]) THEN
  REWRITE_TAC [FUN_EQ_THM] THEN
  LIST_INDUCT_TAC THEN ASM_REWRITE_TAC [read_byte_val; obind]);;

