   OPERAND8 (%ah) s = RAX :> bottom_32 :> bottom_16 :> top_8 /\
   OPERAND8 (%ch) s = RCX :> bottom_32 :> bottom_16 :> top_8 /\
   OPERAND8 (%dh) s = RDX :> bottom_32 :> bottom_16 :> top_8 /\
   OPERAND8 (%bh) s = RBX :> bottom_32 :> bottom_16 :> top_8 /\
